namespace InventoryApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using InventoryApp.Models;

namespace InventoryApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a slow data source (e.g. database / API call)
        await Task.Delay(800);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Hydraulic Press",    Location = "Building A - Bay 3",  LastInspected = new DateTime(2026, 5, 12) },
            new() { Id = 2, Name = "CNC Lathe",          Location = "Building B - Shop 1", LastInspected = new DateTime(2026, 4, 28) },
            new() { Id = 3, Name = "Overhead Crane",     Location = "Building A - Bay 1",  LastInspected = new DateTime(2026, 3, 15) },
            new() { Id = 4, Name = "Arc Welder",         Location = "Building C - Weld Lab", LastInspected = new DateTime(2026, 5, 30) },
            new() { Id = 5, Name = "Band Saw",           Location = "Building B - Shop 2", LastInspected = new DateTime(2026, 2, 20) },
            new() { Id = 6, Name = "Forklift #7",        Location = "Warehouse East",      LastInspected = new DateTime(2026, 5, 1)  },
            new() { Id = 7, Name = "Air Compressor",     Location = "Building A - Utility", LastInspected = new DateTime(2026, 1, 10) },
            new() { Id = 8, Name = "Paint Booth",        Location = "Building D - Finish", LastInspected = new DateTime(2026, 4, 5)  },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@attribute [StreamRendering(true)]
@using InventoryApp.Models
@using InventoryApp.Services
@inject EquipmentService EquipmentService

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? items;

    protected override async Task OnInitializedAsync()
    {
        items = await EquipmentService.GetEquipmentAsync();
    }
}

